// Embeds assets-private/visibility_checklist.pdf into the Pages Function as a
// base64 string module (functions/_lib/checklistPdf.ts). The PDF must not sit in
// public/, or Cloudflare Pages would serve it as an open static asset. Runs first
// in `npm run build`; Pages compiles functions/ after the build command finishes.
// The generated file is gitignored.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const src = resolve(root, 'assets-private/visibility_checklist.pdf');
const out = resolve(root, 'functions/_lib/checklistPdf.ts');

const bytes = readFileSync(src);
if (bytes.length === 0 || bytes.subarray(0, 5).toString('latin1') !== '%PDF-') {
  throw new Error(`build-checklist-pdf: ${src} is missing or not a PDF`);
}

mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// GENERATED by scripts/build-checklist-pdf.mjs. Do not edit or commit.\n` +
    `export const CHECKLIST_PDF_BYTES = ${bytes.length};\n` +
    `export const CHECKLIST_PDF_BASE64 =\n  '${bytes.toString('base64')}';\n`,
);
console.log(`build-checklist-pdf: embedded ${bytes.length} bytes -> functions/_lib/checklistPdf.ts`);
